package com.zy.zhangyun;

import android.app.*;import android.os.*;import android.text.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.net.*;import java.text.*;import java.util.*;import java.util.concurrent.*;

public class ExchangeActivity extends Activity {
  private TextView updated,summary,pairTitle,pairSubtitle,chartInfo,baseSelect,quoteSelect,rateType,settlementType,dataNote,trendSelect; private CandleChartView chart;private TrendChartView trendChart;
  private String base="CNY",quote="AUD",pricing="市场牌价",settlement="现汇";private boolean isTrend=false;private int days=1;private final LinkedHashSet<String> trendQuotes=new LinkedHashSet<>(Arrays.asList("AUD","USD"));private final ExecutorService pool=Executors.newSingleThreadExecutor();private final Handler handler=new Handler(Looper.getMainLooper());
  public void onCreate(Bundle s){super.onCreate(s);setContentView(R.layout.activity_exchange);updated=findViewById(R.id.updated);summary=findViewById(R.id.summary);pairTitle=findViewById(R.id.pair_title);pairSubtitle=findViewById(R.id.pair_subtitle);chartInfo=findViewById(R.id.chart_info);chart=findViewById(R.id.chart);trendChart=findViewById(R.id.trend_chart);baseSelect=findViewById(R.id.base_select);quoteSelect=findViewById(R.id.quote_select);rateType=findViewById(R.id.rate_type);settlementType=findViewById(R.id.settlement_type);dataNote=findViewById(R.id.data_note);trendSelect=findViewById(R.id.trend_select);
    findViewById(R.id.refresh).setOnClickListener(v->load());baseSelect.setOnClickListener(v->pickCurrency(true));quoteSelect.setOnClickListener(v->pickCurrency(false));rateType.setOnClickListener(v->pickPricing());settlementType.setOnClickListener(v->pickSettlement());trendSelect.setOnClickListener(v->pickTrendCurrencies());
    ((RadioGroup)findViewById(R.id.chart_mode)).setOnCheckedChangeListener((g,id)->{isTrend=id==R.id.mode_trend;updateMode();loadHistory();});((RadioGroup)findViewById(R.id.range_group)).setOnCheckedChangeListener((g,id)->{days=id==R.id.range_3d?3:id==R.id.range_7d?7:id==R.id.range_1m?31:id==R.id.range_3m?92:id==R.id.range_6m?183:id==R.id.range_1y?365:id==R.id.range_2y?730:1;loadHistory();});syncChoices();updateMode();load();}
  protected void onResume(){super.onResume();handler.postDelayed(tick,60000);}protected void onPause(){super.onPause();handler.removeCallbacks(tick);}private final Runnable tick=new Runnable(){public void run(){load();handler.postDelayed(this,60000);}};
  private void syncChoices(){baseSelect.setText("基准币种："+base);quoteSelect.setText("兑换币种："+quote);rateType.setText(pricing);settlementType.setText(settlement);trendSelect.setText("对比币种："+join(trendQuotes));dataNote.setText(pricing.equals("市场牌价")?"数据说明：市场牌价来自公开外汇参考价；非银行实际成交价，仅供参考。":"数据说明：银行买入价因银行、地区、渠道和现汇/现钞不同而异。请选择指定银行的数据接口后才可提供可交易报价。");}
  private void updateMode(){chart.setVisibility(isTrend?View.GONE:View.VISIBLE);trendChart.setVisibility(isTrend?View.VISIBLE:View.GONE);trendSelect.setVisibility(isTrend?View.VISIBLE:View.GONE);}
  private String join(Collection<String> c){return android.text.TextUtils.join("、",c);}
  private void pickCurrency(boolean isBase){ArrayList<String> items=new ArrayList<>();String[] popular={"CNY","USD","EUR","AUD","JPY","GBP"};LinkedHashSet<String> order=new LinkedHashSet<>(Arrays.asList(popular));ArrayList<String> rest=new ArrayList<>();for(Currency c:Currency.getAvailableCurrencies())if(!order.contains(c.getCurrencyCode()))rest.add(c.getCurrencyCode());Collections.sort(rest);order.addAll(rest);for(String code:order)try{items.add(code+"  ·  "+Currency.getInstance(code).getDisplayName(Locale.CHINA));}catch(Exception ignored){}LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);int pad=(int)(16*getResources().getDisplayMetrics().density);box.setPadding(pad,0,pad,0);EditText search=new EditText(this);search.setHint("搜索代码或货币名称，例如 JPY / 日元");box.addView(search);ListView list=new ListView(this);ArrayAdapter<String> a=new ArrayAdapter<String>(this,android.R.layout.simple_list_item_1,items);list.setAdapter(a);box.addView(list,new LinearLayout.LayoutParams(-1,(int)(360*getResources().getDisplayMetrics().density)));AlertDialog dialog=new AlertDialog.Builder(this).setTitle(isBase?"选择基准币种":"选择兑换币种").setView(box).setNegativeButton("取消",null).create();search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence x,int y,int z,int q){}public void onTextChanged(CharSequence x,int y,int z,int q){a.getFilter().filter(x);}public void afterTextChanged(Editable e){}});list.setOnItemClickListener((p,v,pos,id)->{String code=a.getItem(pos).substring(0,3);if(isBase){base=code;if(base.equals(quote))quote="USD".equals(base)?"EUR":"USD";trendQuotes.remove(base);}else{quote=code;if(quote.equals(base))base="USD".equals(quote)?"EUR":"USD";}syncChoices();dialog.dismiss();load();});dialog.show();}
  private void pickPricing(){String[] v={"市场牌价","银行买入价"};new AlertDialog.Builder(this).setTitle("选择价格类型").setSingleChoiceItems(v,pricing.equals(v[0])?0:1,(d,w)->{pricing=v[w];syncChoices();d.dismiss();load();}).show();}
  private void pickSettlement(){String[] v={"现汇","现钞"};new AlertDialog.Builder(this).setTitle("选择交割方式").setSingleChoiceItems(v,settlement.equals(v[0])?0:1,(d,w)->{settlement=v[w];syncChoices();d.dismiss();load();}).show();}
  private void pickTrendCurrencies(){final String[] options={"AUD","USD","EUR","JPY","GBP","HKD","CAD","NZD","SGD","CHF"};boolean[] checked=new boolean[options.length];for(int i=0;i<options.length;i++)checked[i]=trendQuotes.contains(options[i]);new AlertDialog.Builder(this).setTitle("选择对比币种（可多选）").setMultiChoiceItems(options,checked,(d,i,on)->{if(on&&!options[i].equals(base))trendQuotes.add(options[i]);else trendQuotes.remove(options[i]);}).setNegativeButton("取消",null).setPositiveButton("确定",(d,w)->{if(trendQuotes.isEmpty())trendQuotes.add(quote);syncChoices();loadHistory();}).show();}
  private void load(){updated.setText("正在同步行情…");if(!pricing.equals("市场牌价")){summary.setText("已选择："+pricing+" · "+settlement+"\n\n请配置具体银行的数据源后获取可交易买入价。\n不同银行的现汇、现钞买入价并不相同。");updated.setText("等待银行报价数据源");loadHistory();return;}loadLatest();loadHistory();}
  private void loadLatest(){pool.execute(()->{try{JSONObject j=new JSONObject(get("https://open.er-api.com/v6/latest/"+base));if(!"success".equals(j.optString("result")))throw new IOException();double value=j.getJSONObject("rates").getDouble(quote);String when=j.optString("time_last_update_utc","");runOnUiThread(()->{summary.setText("1 "+base+" = "+String.format(Locale.US,"%.6f",value)+" "+quote);updated.setText("行情更新："+when+"  ·  自动每分钟刷新");});}catch(Exception e){runOnUiThread(()->updated.setText("行情暂时无法同步，请检查网络后重试"));}});}
  private void loadHistory(){final String b=base;final int d=days;final boolean trend=isTrend;final ArrayList<String> targets=new ArrayList<>(trendQuotes);if(!trend){targets.clear();targets.add(quote);}pairTitle.setText(trend?b+" 多币种走势":b+" / "+quote);pairSubtitle.setText(trend?"以首个交易日为 100% 进行涨跌对比":"1 "+b+" 可兑换 "+quote+" · 日 K 线");chartInfo.setText("正在加载历史曲线…");pool.execute(()->{try{Calendar cal=Calendar.getInstance(TimeZone.getTimeZone("UTC"));cal.add(Calendar.DATE,-(d+14));String start=new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(cal.getTime());String end=new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date());String to=android.text.TextUtils.join(",",targets);JSONObject j=new JSONObject(get("https://api.frankfurter.app/"+start+".."+end+"?from="+b+"&to="+to));JSONObject rates=j.getJSONObject("rates");ArrayList<String> dates=new ArrayList<>();Iterator<String> it=rates.keys();while(it.hasNext())dates.add(it.next());Collections.sort(dates);if(!trend)showCandles(dates,rates,targets.get(0),d);else showTrend(dates,rates,targets,d);}catch(Exception e){runOnUiThread(()->{chart.setCandles(null);trendChart.setSeries(null,"","");chartInfo.setText("该币种或区间暂无历史数据");});}});}
  private void showCandles(ArrayList<String> dates,JSONObject rates,String target,int d)throws Exception{int keep=Math.min(d<=1?2:d,dates.size());int from=Math.max(0,dates.size()-keep);ArrayList<String> used=new ArrayList<>(dates.subList(from,dates.size()));ArrayList<Double> values=new ArrayList<>();for(String x:used)values.add(rates.getJSONObject(x).getDouble(target));List<CandleChartView.Candle> out=new ArrayList<>();for(int i=0;i<values.size();i++){double open=i==0?values.get(i):values.get(i-1),close=values.get(i);out.add(new CandleChartView.Candle(used.get(i).substring(5),open,Math.max(open,close),Math.min(open,close),close));}runOnUiThread(()->{chart.setCandles(out);if(values.size()>0){double change=(values.get(values.size()-1)/values.get(0)-1)*100;chartInfo.setText("日 K："+used.get(0)+" 至 "+used.get(used.size()-1)+"    "+String.format(Locale.US,"%+.2f%%",change)+"    "+values.size()+" 个交易日");}else chartInfo.setText("该区间暂无日 K 数据");});}
  private void showTrend(ArrayList<String> dates,JSONObject rates,ArrayList<String> targets,int d)throws Exception{int keep=Math.min(d<=1?2:d,dates.size());int from=Math.max(0,dates.size()-keep);ArrayList<String> used=new ArrayList<>(dates.subList(from,dates.size()));LinkedHashMap<String,List<Double>> series=new LinkedHashMap<>();for(String code:targets){ArrayList<Double> vs=new ArrayList<>();for(String date:used)vs.add(rates.getJSONObject(date).getDouble(code));series.put(code,vs);}runOnUiThread(()->{trendChart.setSeries(series,used.get(0).substring(5),used.get(used.size()-1).substring(5));chartInfo.setText("走势对比："+used.size()+" 个交易日；各币种以起点为基准显示涨跌。");});}
  private String get(String address)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(address).openConnection();c.setConnectTimeout(9000);c.setReadTimeout(12000);c.setRequestProperty("Accept","application/json");try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buf=new byte[4096];for(int n;(n=in.read(buf))!=-1;)out.write(buf,0,n);return out.toString("UTF-8");}}
}
